var font=AssetDatabase.LoadAssetAtPath<TMPro.TMP_FontAsset>("Assets/Proto/MountainPass/Settings/MountainKorean.asset");var words=System.IO.Directory.GetFiles("Assets/Proto/MountainPass/Scripts","*.cs").Select(System.IO.File.ReadAllText);var characters=new string(string.Concat(words).Where(c=>c>=0xAC00&&c<=0xD7A3).Distinct().ToArray());string missing;bool all=font.TryAddCharacters(characters,out missing);for(int i=0;i<font.atlasTextures.Length;i++){var atlas=font.atlasTextures[i];if(atlas==null)continue;atlas.name="T_MountainKorean_Atlas_"+i;if(!AssetDatabase.Contains(atlas))AssetDatabase.AddObjectToAsset(atlas,font);EditorUtility.SetDirty(atlas);}EditorUtility.SetDirty(font);AssetDatabase.SaveAssetIfDirty(font);return new{all,missing,atlases=font.atlasTextures.Where(t=>t!=null).Select(t=>new{t.name,t.width,t.height}).ToArray(),glyphs=font.characterTable.Count};
